wizard.saveScript:
/* add save script to add status = copyright for any portion where status is blank */

var all = xml.getAllSubtrees('/item/copyright/portions/portion/sections/section/');
for(var i=0;i<all.length;i++)
{
	if(all[i].get('copyrightstatus')=='')
	{
	   all[i].set('copyrightstatus','copyright');
	}
}

/* new save scripts */

var DEBUG = true;
// FUNCTIONS
function debuglog( message ) { 
	if ( DEBUG == 'True' ) { logger.log(message); }
}
function setCollection(xpath) {
	xml.set(xpath, currentItem.getCollection().getName());
}
function setOrigination(sxpath, dxpath) {
	xml.deleteAll(dxpath);
	if ( xml.get(sxpath) == 'MERLOT' ) { xml.set(dxpath, 'MERLOT'); }
	else if ( xml.get(sxpath) == 'Books - Libraries Australia' ) { xml.set(dxpath, 'Books - Libraries Australia'); } 
	else if ( xml.get(sxpath) == 'Journals - Libraries Australia' ) { xml.set(dxpath, 'Journals - Libraries Australia'); } 
	else if ( xml.get(sxpath) == 'OER' ) { xml.set(dxpath, 'OER Purchase'); } 
	else { xml.set(dxpath, 'Contributed'); }
}
function addOriginalContributor(destXpath)
{
	debuglog('begin addOriginalContributor with ' + destXpath);
	if (!xml.exists(destXpath))
	{
		var destNode = xml.createSubtree(destXpath);
		destNode.set('username', user.getUsername());
		destNode.set('firstName', user.getFirstName());
		destNode.set('lastName', user.getLastName());
		destNode.set('email', user.getEmail());
	}
	else
	{
		debuglog('destXpath already exits!');
	}
}
function addMetadata(xpath, metadata) {
	debuglog('Adding ' + metadata + ' to ' + xpath);
	var em = xml.getAll(xpath);
	var el = em.length;
	if ( el != 0 ) {
		var eme = 'False';
		for ( var ei = 0; ei < el; ei++ ) {
			if ( em[ei] == metadata ) { eme = 'True'; }
		}
		if ( eme == 'False' ) { xml.add(xpath, metadata); }
	} else {
		xml.add(xpath, metadata);
	}
}
function registerAttachmentFormat(xpath) {
	xml.deleteAll(xpath);
	debuglog('Registering Attachment Format');
	var aAtt = attachments.list();
	var aTS = aAtt.size();
	for ( var ai = 0; ai < aTS; ai++ ) {
		var tAtt = aAtt.get(ai);
		debuglog('Attachment UUID: ' + tAtt.getUuid() + '.  Attachment Type: ' + tAtt.getUuid());
		var tAT = tAtt.getType();
		if (tAT == 'FILE') {
			var fMT = mime.getMimeTypeForFilename(tAtt.getFilename());
			if ( fMT != null ) {
				debuglog('Attachment Filename is: ' + tAtt.getFilename() + '.  Attachment MIME type: ' + mime.getMimeTypeForFilename(tAtt.getFilename()).getType() + '.  Attachment MIME type Description: ' + mime.getMimeTypeForFilename(tAtt.getFilename()).getDescription());
				addMetadata(xpath, mime.getMimeTypeForFilename(tAtt.getFilename()).getDescription());
			} else {
				addMetadata(xpath, 'Unknown');
			}
		}
		if (tAT == 'IMS') {
			debuglog('Attachment is IMS.  Attachment Filename is: ' + tAtt.getFilename());
			addMetadata(xpath, 'IMS');
		}
		if (tAT == 'ZIP') {
			debuglog('Attachment is ZIP.  Attachment Filename is: ' + tAtt.getFilename());
			addMetadata(xpath, 'ZIP');
		}
		if (tAT == 'LINK') {
			debuglog('Attachment is URL.  Attachment URL is: ' + tAtt.getUrl());
			addMetadata(xpath, 'URL');
		}
		if (tAT == 'HTML') {
			debuglog('Attachment is HTML.  Attachment Filename is: ' + tAtt.getFilename());
			addMetadata(xpath, 'HTML Page');
		}
		if (tAT == 'CUSTOM') {
			debuglog('Attachment is CUSTOM.  Custom type is: ' + tAtt.getCustomType());
			var customType = tAtt.getCustomType();
			if ( customType == 'flikr' ) {
				addMetadata(xpath, 'Flikr Photo');
				addMetadata(xpath, 'Image');
			}
			if ( customType == 'youtube') {
				addMetadata(xpath, 'YouTube Video');
				addMetadata(xpath, 'Video');
			}
			if ( customType == 'kaltura') {
				addMetadata(xpath, 'Streaming Video');
				addMetadata(xpath, 'Video');
			}
			if (customType == 'scorm' ) {
				addMetadata(xpath, 'SCORM');
			}
		}
	}
}

// Main Area
xml.set('item/lom/educational/learning.resource.type', 'eReserve Reading');
addOriginalContributor('item/itembody/originalContributor');
registerAttachmentFormat('item/lom/technical/format');
setCollection('item/itembody/collection');
setOrigination('item/itembody/meta/switches/itemType', 'item/itembody/origination');
